package com.raccooncoefficient;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import net.runelite.api.gameval.InterfaceID;

/**
 * Decides which hovered widget is an equippable item surface.
 * The numbers come from the menu entry's widget. This does not scan a bank.
 */
public final class EquipmentHover
{
	public static final int NO_ITEM = -1;

	private static final Set<Integer> EQUIPMENT_SLOTS = Collections.unmodifiableSet(new HashSet<Integer>(Arrays.asList(
		InterfaceID.Equipment.SLOT0,
		InterfaceID.Equipment.SLOT1,
		InterfaceID.Equipment.SLOT2,
		InterfaceID.Equipment.SLOT3,
		InterfaceID.Equipment.SLOT4,
		InterfaceID.Equipment.SLOT5,
		InterfaceID.Equipment.SLOT7,
		InterfaceID.Equipment.SLOT9,
		InterfaceID.Equipment.SLOT10,
		InterfaceID.Equipment.SLOT12,
		InterfaceID.Equipment.SLOT13,
		InterfaceID.Equipment.EXTRA_QUIVER_SLOT,
		InterfaceID.Equipment.EXTRA_QUIVER_AMMO)));

	private EquipmentHover()
	{
	}

	public static int itemId(int groupId, int widgetId, int parentId, int widgetItemId, int childItemId)
	{
		if (groupId == InterfaceID.WORNITEMS
			|| (groupId == InterfaceID.BANKMAIN && parentId == InterfaceID.Bankside.WORNOPS))
		{
			return positive(childItemId);
		}

		if (widgetId == InterfaceID.Inventory.ITEMS
			|| widgetId == InterfaceID.Bankmain.ITEMS
			|| widgetId == InterfaceID.SharedBank.ITEMS
			|| widgetId == InterfaceID.GeOffersSide.ITEMS
			|| groupId == InterfaceID.EQUIPMENT_SIDE
			|| groupId == InterfaceID.BANKSIDE
			|| groupId == InterfaceID.SHARED_BANK_SIDE
			|| EQUIPMENT_SLOTS.contains(Integer.valueOf(widgetId)))
		{
			return positive(widgetItemId);
		}

		return NO_ITEM;
	}

	/**
	 * Resolve a menu entry only if its widget is a known inventory/equipment
	 * surface. Prefer the menu's own item ID, which identifies the specific
	 * item under the cursor, over a container or generic parent widget ID.
	 * A direct child item widget may have its parent as the item container.
	 * Unrelated menus and missing IDs are never guessed.
	 */
	public static int menuItemId(
		int groupId,
		int widgetId,
		int parentId,
		int menuItemId,
		int widgetItemId)
	{
		if (!supportedSurface(groupId, widgetId, parentId))
		{
			return NO_ITEM;
		}
		if (menuItemId > 0)
		{
			return menuItemId;
		}
		// A container widget (for example Inventory.ITEMS) is not itself a
		// uniquely hovered item. If the menu doesn't provide an item ID,
		// use the widget's ID only for explicit slot or item-child surfaces.
		// Unknown is safer than showing the first/stale item in a container.
		if (explicitItemWidget(widgetId, parentId, groupId))
		{
			return positive(widgetItemId);
		}
		return NO_ITEM;
	}

	private static boolean explicitItemWidget(int widgetId, int parentId, int groupId)
	{
		return EQUIPMENT_SLOTS.contains(Integer.valueOf(widgetId))
			|| EQUIPMENT_SLOTS.contains(Integer.valueOf(parentId))
			|| parentId == InterfaceID.Inventory.ITEMS
			|| parentId == InterfaceID.Bankmain.ITEMS
			|| parentId == InterfaceID.SharedBank.ITEMS
			|| parentId == InterfaceID.GeOffersSide.ITEMS
			|| parentId == InterfaceID.Bankside.WORNOPS
			|| groupId == InterfaceID.WORNITEMS
			|| groupId == InterfaceID.EQUIPMENT_SIDE
			|| groupId == InterfaceID.BANKSIDE
			|| groupId == InterfaceID.SHARED_BANK_SIDE;
	}

	private static boolean supportedSurface(int groupId, int widgetId, int parentId)
	{
		if (widgetId == InterfaceID.Inventory.ITEMS || parentId == InterfaceID.Inventory.ITEMS
			|| widgetId == InterfaceID.Bankmain.ITEMS || parentId == InterfaceID.Bankmain.ITEMS
			|| widgetId == InterfaceID.SharedBank.ITEMS || parentId == InterfaceID.SharedBank.ITEMS
			|| widgetId == InterfaceID.GeOffersSide.ITEMS || parentId == InterfaceID.GeOffersSide.ITEMS
			|| EQUIPMENT_SLOTS.contains(Integer.valueOf(widgetId))
			|| EQUIPMENT_SLOTS.contains(Integer.valueOf(parentId)))
		{
			return true;
		}
		// Worn equipment, side equipment, and bank side slots are item
		// surfaces, but their dynamic child IDs can change across UIs.
		return groupId == InterfaceID.WORNITEMS
			|| groupId == InterfaceID.EQUIPMENT_SIDE
			|| groupId == InterfaceID.BANKSIDE
			|| groupId == InterfaceID.SHARED_BANK_SIDE
			|| (groupId == InterfaceID.BANKMAIN
				&& parentId == InterfaceID.Bankside.WORNOPS);
	}

	private static int positive(int itemId)
	{
		return itemId > 0 ? itemId : NO_ITEM;
	}
}

package com.raccooncoefficient;

import com.raccooncoefficient.score.GearScoreBreakdown;
import com.raccooncoefficient.score.GearScoreCalculator;
import com.raccooncoefficient.score.GearScoreText;
import com.raccooncoefficient.score.ItemStatSource;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Displays the total equipped Gear Score immediately above the helmet slot.
 *
 * IMPORTANT: The original MANUAL drawAfterInterface(InterfaceID.EQUIPMENT)
 * hook compiled and our unit render() test passed, yet the actual logged-in
 * player screenshot showed no label. Use the same ABOVE_WIDGETS top-level
 * render phase as RuneLite's working tooltip overlay instead. RuneLite maps
 * ABOVE_WIDGETS to all three top-level interface variants.
 *
 * This checks the live equipment widgets each frame; no widget is modified.
 */
public class EquipmentScoreOverlay extends Overlay
{
	private static final Logger log = LoggerFactory.getLogger(EquipmentScoreOverlay.class);

	private final Client client;
	private final ItemStatSource stats;
	private final GearScoreCalculator calculator;
	private String lastRenderState;

	@Inject
	EquipmentScoreOverlay(Client client, RuneLiteItemStatSource stats, RuneLiteItemNameSource names)
	{
		this(client, stats, GearScoreCalculator.wave3(names));
	}

	/** Test seam; the production constructor uses real RuneLite sources. */
	EquipmentScoreOverlay(Client client, ItemStatSource stats, GearScoreCalculator calculator)
	{
		this.client = client;
		this.stats = stats;
		this.calculator = calculator;
		setPosition(OverlayPosition.DYNAMIC);
		// Registered by OverlayManager for TOPLEVEL, TOPLEVEL_OSRS_STRETCH
		// and TOPLEVEL_PRE_EOC. Avoid double rendering through another hook.
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Widget helmet = client.getWidget(InterfaceID.Equipment.SLOT0);
		if (helmet == null)
		{
			report("helmet widget unavailable; equipment screen not open or ID unresolvable");
			return null;
		}
		if (helmet.isHidden())
		{
			report("helmet widget hidden");
			return null;
		}

		Rectangle helmetBounds = helmet.getBounds();
		if (helmetBounds == null || helmetBounds.width < 20 || helmetBounds.height < 20)
		{
			report("helmet widget bounds unavailable");
			return null;
		}

		Widget panel = client.getWidget(InterfaceID.Equipment.UNIVERSE);
		if (panel != null && panel.isHidden())
		{
			report("equipment panel hidden");
			return null;
		}
		Rectangle panelBounds = panel == null ? null : panel.getBounds();
		if (!GearScoreHelmetLayout.isUsablePanel(panelBounds, helmetBounds))
		{
			// Some native layouts expose a widget with zero/unrelated root
			// bounds. Anchor the guarded strip to the observed helmet widget
			// rather than discarding a valid visible equipment screen.
			panelBounds = GearScoreHelmetLayout.fallbackPanel(helmetBounds);
		}

		java.util.List<com.raccooncoefficient.score.WornItem> worn = WornEquipment.read(client);
		String line;
		if (worn == null)
		{
			line = "Gear Score: ?";
		}
		else
		{
			GearScoreBreakdown score = calculator.score(worn, stats);
			line = GearScoreText.equipmentLine(score);
		}

		boolean drew = drawLine(graphics, panelBounds, helmetBounds, line);
		report(drew ? "visible over helmet" : "layout blocked; label hidden to avoid overlap");
		return null;
	}

	private boolean drawLine(Graphics2D graphics, Rectangle panel, Rectangle helmet, String line)
	{
		Font previousFont = graphics.getFont();
		Color previousColor = graphics.getColor();
		java.awt.Shape previousClip = graphics.getClip();
		try
		{
			graphics.setFont(FontManager.getRunescapeSmallFont());
			String compact = GearScoreText.compactEquipmentLine(line);
			GearScoreHelmetLayout.Placement placement = GearScoreHelmetLayout.choose(
				panel, helmet,
				graphics.getFontMetrics().stringWidth(line),
				graphics.getFontMetrics().stringWidth(compact));
			if (placement.getLabel() == GearScoreHelmetLayout.Label.HIDDEN)
			{
				return false;
			}

			String display = placement.getLabel() == GearScoreHelmetLayout.Label.FULL
				? line : compact;
			int baseline = placement.getBaseline();
			int x = placement.getX();

			graphics.clipRect(x - 1, baseline - 16, placement.getWidth() + 3, 19);
			RaccoonMark.draw(graphics, x, baseline - RaccoonMark.HEIGHT);

			int textX = x + RaccoonMark.WIDTH + 3;
			graphics.setColor(Color.BLACK);
			graphics.drawString(display, textX + 1, baseline + 1);
			graphics.setColor(GearScoreText.EQUIPMENT_ORANGE);
			graphics.drawString(display, textX, baseline);
			return true;
		}
		finally
		{
			graphics.setFont(previousFont);
			graphics.setColor(previousColor);
			graphics.setClip(previousClip);
		}
	}

	/**
	 * Log only when the display state changes. This is native diagnostic
	 * evidence without a constant per-frame log flood or item/account data.
	 */
	private void report(String current)
	{
		if (!current.equals(lastRenderState))
		{
			lastRenderState = current;
			log.info("Raccoon Coefficient total: {}", current);
		}
	}
}

package com.raccooncoefficient;

import com.raccooncoefficient.score.GearScoreBreakdown;
import com.raccooncoefficient.score.GearScorer;
import com.raccooncoefficient.score.SelectableGearScorer;
import com.raccooncoefficient.score.GearScoreText;
import com.raccooncoefficient.score.ItemStatSource;
import java.awt.Rectangle;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.FontID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetPositionMode;
import net.runelite.api.widgets.WidgetTextAlignment;
import net.runelite.api.widgets.WidgetType;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * The displayed equipped total is a REAL RuneLite equipment-interface text
 * widget, NOT an overlay competing with the modal's drawing order.
 *
 * This is the same interface-child API RuneLite's own Wiki DPS manager uses
 * to add a button to the Equipment screen.
 *
 * Must only be called on RuneLite's client thread (event subscribers and
 * ClientThread.invoke). Never deletes children owned by other plugins.
 */
@Singleton
final class EquipmentTotalWidget
{
	private static final Logger log = LoggerFactory.getLogger(EquipmentTotalWidget.class);
	private static final String OWNER_NAME = "raccoon-coefficient-equipped-total";
	private static final int LABEL_WIDTH = 170;
	private static final int LABEL_HEIGHT = 20;
	private static final int GAP_ABOVE_HELMET = 5;
	private static final int TEXT_COLOR = 0xff981f;

	private final Client client;
	private final ItemStatSource stats;
	private final GearScorer calculator;
	private Widget label;
	private Widget parent;
	private String lastStatus;

	@Inject
	EquipmentTotalWidget(Client client, RuneLiteItemStatSource stats, RuneLiteItemNameSource names,
		RaccoonCoefficientConfig config)
	{
		this(client, stats, new SelectableGearScorer(config::scoringModel, names));
	}

	/** Test seam; normal construction uses the RuneLite item data sources. */
	EquipmentTotalWidget(Client client, ItemStatSource stats, GearScorer calculator)
	{
		this.client = client;
		this.stats = stats;
		this.calculator = calculator;
	}

	void refresh()
	{
		Widget helmet = client.getWidget(InterfaceID.Equipment.SLOT0);
		Widget contents = client.getWidget(InterfaceID.Equipment.CONTENTS);
		if (helmet == null || contents == null || helmet.isHidden() || contents.isHidden())
		{
			hide();
			status("equipment interface or helmet not visible");
			return;
		}

		Rectangle helm = helmet.getBounds();
		Widget actualParent = helmet.getParent();
		if (actualParent == null || actualParent.isHidden()
			|| !canContainLabel(actualParent.getBounds(), helm))
		{
			actualParent = contents;
		}
		Rectangle area = actualParent.getBounds();
		if (helm == null || area == null || helm.width < 20 || helm.height < 20
			|| area.width < 160 || area.height < 80)
		{
			hide();
			status("equipment widget bounds unavailable");
			return;
		}
		// Parent-relative geometry in the actual game UI, not screen-space
		// Graphics2D coordinates and not the modal's top-level overlay pass.
		int x = helm.x + helm.width / 2 - LABEL_WIDTH / 2 - area.x;
		int y = helm.y - GAP_ABOVE_HELMET - LABEL_HEIGHT - area.y;
		if (x < 0 || y < 0 || x + LABEL_WIDTH > area.width
			|| y + LABEL_HEIGHT > area.height)
		{
			hide();
			status("helmet label would exceed equipment parent bounds");
			return;
		}

		Widget current = locateOwnedChild(actualParent);
		if (current == null)
		{
			current = actualParent.createChild(-1, WidgetType.TEXT);
			if (current == null)
			{
				status("failed to create equipment interface text child");
				return;
			}
			current.setName(OWNER_NAME)
				.setTextColor(TEXT_COLOR)
				.setFontId(FontID.BOLD_12)
				.setTextShadowed(true)
				.setXTextAlignment(WidgetTextAlignment.CENTER)
				.setYTextAlignment(WidgetTextAlignment.CENTER)
				.setHasListener(false);
			current.setNoClickThrough(false);
			current.setNoScrollThrough(false);
		}

		parent = actualParent;
		label = current;
		List<com.raccooncoefficient.score.WornItem> worn = WornEquipment.read(client);
		String text = worn == null ? "Gear Score: ?"
			: GearScoreText.equipmentLine(calculator.score(worn, stats));
		if (!text.equals(current.getText()))
		{
			current.setText(text);
		}
		current.setPos(x, y, WidgetPositionMode.ABSOLUTE_LEFT,
			WidgetPositionMode.ABSOLUTE_TOP);
		current.setSize(LABEL_WIDTH, LABEL_HEIGHT);
		current.setHidden(false);
		current.revalidate();
		status("equipment text child active above helmet");
	}

	void hide()
	{
		if (label != null)
		{
			label.setHidden(true);
		}
	}

	void shutdown()
	{
		// A single child cannot be deleted through Widget API. Keep it
		// invisible, without deleting unrelated dynamic children; a later
		// plugin restart reuses the matching owned-name child.
		hide();
		label = null;
		parent = null;
		lastStatus = null;
	}

	private static boolean canContainLabel(Rectangle area, Rectangle helm)
	{
		if (area == null || helm == null || area.width < LABEL_WIDTH
			|| area.height < LABEL_HEIGHT || helm.width < 20 || helm.height < 20)
		{
			return false;
		}
		int centre = helm.x + helm.width / 2;
		int left = centre - LABEL_WIDTH / 2;
		int top = helm.y - GAP_ABOVE_HELMET - LABEL_HEIGHT;
		return left >= area.x && top >= area.y
			&& left + LABEL_WIDTH <= area.x + area.width
			&& top + LABEL_HEIGHT <= area.y + area.height;
	}

	private Widget locateOwnedChild(Widget actualParent)
	{
		if (actualParent == parent && label != null)
		{
			// Ensure this reference still belongs to this live parent.
			Widget[] children = actualParent.getDynamicChildren();
			if (children != null)
			{
				for (Widget child : children)
				{
					if (child == label && OWNER_NAME.equals(child.getName()))
					{
						return child;
					}
				}
			}
		}
		Widget[] children = actualParent.getDynamicChildren();
		if (children != null)
		{
			for (Widget child : children)
			{
				if (child != null && OWNER_NAME.equals(child.getName()))
				{
					return child;
				}
			}
		}
		return null;
	}

	private void status(String next)
	{
		if (!next.equals(lastStatus))
		{
			lastStatus = next;
			log.info("Raccoon Coefficient total widget: {}", next);
		}
	}
}

package com.raccooncoefficient;

import java.awt.Rectangle;

/**
 * Pure-Java equipment-title placement calculation.
 *
 * The draw call must measure text with the actual RuneScape font before
 * selection. A line that does not fit is shortened, then hidden, never
 * clipped across the vanilla title. This does not alter any game widget.
 */
final class GearScoreHeaderLayout
{
	enum Label { FULL, COMPACT, HIDDEN }

	static final class Placement
	{
		private final Label label;
		private final int x;
		private final int baseline;
		private final int right;

		private Placement(Label label, int x, int baseline, int right)
		{
			this.label = label;
			this.x = x;
			this.baseline = baseline;
			this.right = right;
		}

		Label getLabel() { return label; }
		int getX() { return x; }
		int getBaseline() { return baseline; }
		int getRight() { return right; }
	}

	private static final float MAX_LEFT_FRACTION = 0.38f;
	private static final int ICON_AND_SPACING = RaccoonMark.WIDTH + 3;

	private GearScoreHeaderLayout()
	{
	}

	static Placement choose(Rectangle root, Rectangle title, int fullTextWidth, int compactTextWidth)
	{
		if (root == null || root.width < 80 || root.height < 80
			|| fullTextWidth < 0 || compactTextWidth < 0)
		{
			return new Placement(Label.HIDDEN, 0, 0, 0);
		}

		int x = root.x + Math.max(6, Math.round(root.width * 8f / 500f));
		int baseline = root.y + Math.round(root.height * 22f / 324f);
		int right = root.x + Math.round(root.width * MAX_LEFT_FRACTION);

		if (title != null && title.width > 0 && title.height > 0
			&& title.y >= root.y - 2
			&& title.y <= root.y + Math.round(root.height * 0.15f))
		{
			int titleLeft = Math.max(root.x, title.x - 4);
			right = Math.min(right, titleLeft);
			int aligned = title.y + title.height - 2;
			int maxAligned = root.y + Math.round(root.height * 0.09f);
			if (aligned >= root.y + 11 && aligned <= maxAligned)
			{
				baseline = aligned;
			}
		}

		int textSpace = right - x - ICON_AND_SPACING - 2;
		Label label = textSpace >= fullTextWidth ? Label.FULL
			: textSpace >= compactTextWidth ? Label.COMPACT : Label.HIDDEN;
		return new Placement(label, x, baseline, right);
	}
}

package com.raccooncoefficient;

import java.awt.Rectangle;

/**
 * Places the TOTAL worn Gear Score in the empty space directly above the
 * helmet slot on the "Equip Your Character" screen (InterfaceID.Equipment).
 *
 * Anchor the position to the actual SLOT0 widget, not the screen/title text:
 * this survives resizable layouts, title translations and alternate UI sizes.
 * Never move or edit game widgets.
 */
final class GearScoreHelmetLayout
{
	enum Label { FULL, COMPACT, HIDDEN }

	static final class Placement
	{
		private final Label label;
		private final int x;
		private final int baseline;
		private final int width;

		private Placement(Label label, int x, int baseline, int width)
		{
			this.label = label;
			this.x = x;
			this.baseline = baseline;
			this.width = width;
		}

		Label getLabel() { return label; }
		int getX() { return x; }
		int getBaseline() { return baseline; }
		int getWidth() { return width; }
	}

	private static final int TEXT_GAP = 3;
	private static final int TOP_GAP = 11;
	private static final int EDGE_MARGIN = 8;

	private GearScoreHelmetLayout()
	{
	}

	/** A widget root can be zero-sized, while the child helmet is drawn. */
	static boolean isUsablePanel(Rectangle panel, Rectangle helmet)
	{
		return panel != null && helmet != null && panel.width >= 160
			&& panel.height >= 145 && panel.intersects(helmet);
	}

	/**
	 * Derive a conservative window-size envelope around the actual visible
	 * helmet. This is only used if RuneLite returns invalid root bounds. The
	 * HELMET is always the anchor, not the derived panel.
	 */
	static Rectangle fallbackPanel(Rectangle helmet)
	{
		if (helmet == null || helmet.width < 20 || helmet.height < 20)
		{
			return null;
		}
		return new Rectangle(
			helmet.x - helmet.width * 2,
			helmet.y - helmet.height * 2,
			Math.max(440, helmet.width * 13),
			Math.max(300, helmet.height * 9));
	}

	static Placement choose(Rectangle panel, Rectangle helmet, int fullWidth, int compactWidth)
	{
		if (panel == null || helmet == null || panel.width < 160 || panel.height < 145
			|| helmet.width < 20 || helmet.height < 20
			|| fullWidth < 0 || compactWidth < 0 || !panel.intersects(helmet))
		{
			return hidden();
		}

		final int centre = helmet.x + helmet.width / 2;
		// This is the gap directly above helmet SLOT0, not the top title bar.
		final int baseline = helmet.y - TOP_GAP;
		final int textTop = baseline - 15;
		if (textTop < panel.y + 42)
		{
			// A cramped or displaced panel should hide, never paint the
			// Gear Score over the native title.
			return hidden();
		}

		// Constrain to the equipment/character half of the panel, so even
		// an extremely long score never overlaps the attack/defence column.
		final int left = panel.x + EDGE_MARGIN;
		final int right = Math.min(panel.x + panel.width - EDGE_MARGIN,
			panel.x + Math.round(panel.width * 0.58f));
		final int fullSize = RaccoonMark.WIDTH + TEXT_GAP + fullWidth;
		final int compactSize = RaccoonMark.WIDTH + TEXT_GAP + compactWidth;

		if (fitsCentered(centre, fullSize, left, right))
		{
			return new Placement(Label.FULL, centre - fullSize / 2, baseline, fullSize);
		}
		if (fitsCentered(centre, compactSize, left, right))
		{
			return new Placement(Label.COMPACT, centre - compactSize / 2, baseline, compactSize);
		}
		return hidden();
	}

	private static boolean fitsCentered(int centre, int size, int left, int right)
	{
		int x = centre - size / 2;
		return size > RaccoonMark.WIDTH && x >= left && x + size <= right;
	}

	private static Placement hidden()
	{
		return new Placement(Label.HIDDEN, 0, 0, 0);
	}
}

package com.raccooncoefficient;

import com.raccooncoefficient.score.GearScorer;
import com.raccooncoefficient.score.SelectableGearScorer;
import com.raccooncoefficient.score.GearScoreComparison;
import com.raccooncoefficient.score.GearScoreText;
import com.raccooncoefficient.score.ItemStatSource;
import com.raccooncoefficient.score.WornItem;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.config.RuneLiteConfig;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.TooltipComponent;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

/**
 * Adds one temporary tooltip while an equippable item is hovered.
 * The tooltip manager clears its list every frame, so this does not edit
 * the item's stored tooltip or remove lines added by other plugins.
 */
public class GearScoreTooltipOverlay extends Overlay
{
	private final Client client;
	private final ItemStatSource stats;
	private final TooltipManager tooltipManager;
	private final RuneLiteConfig runeLiteConfig;
	private final GearScorer calculator;

	@Inject
	GearScoreTooltipOverlay(
		Client client,
		RuneLiteItemStatSource stats,
		RuneLiteItemNameSource names,
		TooltipManager tooltipManager,
		RuneLiteConfig runeLiteConfig,
		RaccoonCoefficientConfig config)
	{
		this(client, stats, new SelectableGearScorer(config::scoringModel, names), tooltipManager, runeLiteConfig);
	}

	/** Testable rendering seam; production still uses the injected RuneLite adapters. */
	GearScoreTooltipOverlay(
		Client client,
		ItemStatSource stats,
		GearScorer calculator,
		TooltipManager tooltipManager,
		RuneLiteConfig runeLiteConfig)
	{
		this.client = client;
		this.stats = stats;
		this.calculator = calculator;
		this.tooltipManager = tooltipManager;
		this.runeLiteConfig = runeLiteConfig;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		// Share RuneLite's full-screen tooltip draw hook (also used by HoverLite
		// and RuneLite's TooltipOverlay); no external plugin dependency.
		drawAfterInterface(InterfaceID.TOPLEVEL_DISPLAY);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		int itemId = hoveredItemId();
		if (itemId == EquipmentHover.NO_ITEM)
		{
			return null;
		}

		List<WornItem> worn = WornEquipment.read(client);
		if (worn == null)
		{
			return null; // no trustworthy equipment state; never preview a fake zero
		}
		GearScoreComparison comparison = calculator.compare(itemId, worn, stats);
		String text = GearScoreText.tooltip(comparison, WornEquipment.contains(worn, itemId));
		if (text != null)
		{
			ScoreTooltipQueue.addOnce(tooltipManager,
				new ReadableTooltip(text, runeLiteConfig.overlayBackgroundColor()));
		}
		return null;
	}

	private int hoveredItemId()
	{
		if (client.isMenuOpen() || client.getMenu() == null)
		{
			return EquipmentHover.NO_ITEM;
		}
		return HoveredEquipmentItem.resolve(client.getMenu().getMenuEntries());
	}

	/**
	 * RuneLite's default tooltip font has no arrows or unicode minus. Fall
	 * back to a font that can draw them for this tooltip only.
	 */
	private static final class ReadableTooltip implements ScoreTooltipQueue.ScoreComponent
	{
		private final TooltipComponent component = new TooltipComponent();

		private ReadableTooltip(String text, Color background)
		{
			component.setText(text);
			component.setBackgroundColor(background);
		}

		@Override
		public Dimension render(Graphics2D graphics)
		{
			Font current = graphics.getFont();
			if (!current.canDisplay('\u2191') || !current.canDisplay('\u2212'))
			{
				graphics.setFont(new Font(Font.SANS_SERIF, current.getStyle(), Math.max(12, current.getSize())));
			}
			try
			{
				return component.render(graphics);
			}
			finally
			{
				graphics.setFont(current);
			}
		}

		@Override
		public Rectangle getBounds()
		{
			return component.getBounds();
		}

		@Override
		public void setPreferredLocation(Point position)
		{
			component.setPreferredLocation(position);
		}

		@Override
		public void setPreferredSize(Dimension dimension)
		{
			component.setPreferredSize(dimension);
		}
	}
}

package com.raccooncoefficient;

import net.runelite.api.MenuEntry;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetUtil;

/**
 * Resolves the current DEFAULT hovered item, not an unrelated lower-priority
 * action hidden underneath it. Uses RuneLite metadata, without editing menus
 * or sharing state/code with HoverLite.
 */
final class HoveredEquipmentItem
{
	private HoveredEquipmentItem()
	{
	}

	static int resolve(MenuEntry[] entries)
	{
		if (entries == null || entries.length == 0)
		{
			return EquipmentHover.NO_ITEM;
		}

		// Match the actual default action shown to the player.
		// Searching backward for *any* eligible widget can accidentally label
		// a background item when a non-item/menu action is currently on top.
		MenuEntry entry = entries[entries.length - 1];
		if (!ItemHoverAction.isItemAction(entry))
		{
			return EquipmentHover.NO_ITEM;
		}

		Widget widget = entry.getWidget();
		if (widget == null)
		{
			return EquipmentHover.NO_ITEM;
		}

		int widgetId = widget.getId();
		int group = WidgetUtil.componentToInterface(widgetId);
		return EquipmentHover.menuItemId(group, widgetId,
			widget.getParentId(), entry.getItemId(), widget.getItemId());
	}
}

package com.raccooncoefficient;

import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.WidgetUtil;

/**
 * Independent item-action policy grounded in RuneLite's menu entry metadata.
 *
 * HoverLite inspired the idea to validate the top action and its source, but
 * no HoverLite source, dependency, state, or configuration is imported.
 * The widget identity is checked separately by EquipmentHover.
 */
final class ItemHoverAction
{
	private ItemHoverAction()
	{
	}

	static boolean isItemAction(MenuEntry entry)
	{
		if (entry == null || entry.getType() == null
			|| entry.getOption() == null || entry.getOption().trim().isEmpty())
		{
			return false;
		}

		MenuAction action = entry.getType();
		switch (action)
		{
			// These menu actions explicitly describe item interactions.
			case ITEM_USE_ON_ITEM:
			case WIDGET_USE_ON_ITEM:
			case ITEM_FIRST_OPTION:
			case ITEM_SECOND_OPTION:
			case ITEM_THIRD_OPTION:
			case ITEM_FOURTH_OPTION:
			case ITEM_FIFTH_OPTION:
			case ITEM_USE:
			case EXAMINE_ITEM:
				return true;

			// CC_OP and widget actions can describe ordinary buttons as well.
			// Confirm the action comes from a supported item interface.
			case CC_OP:
			case WIDGET_FIRST_OPTION:
			case WIDGET_SECOND_OPTION:
			case WIDGET_THIRD_OPTION:
			case WIDGET_FOURTH_OPTION:
			case WIDGET_FIFTH_OPTION:
			case WIDGET_TARGET:
			case WIDGET_TARGET_ON_WIDGET:
			case RUNELITE_WIDGET:
				return isItemGroup(WidgetUtil.componentToInterface(entry.getParam1()));

			// In particular, RUNELITE_OVERLAY/CONFIG, LOW_PRIORITY, NPC,
			// object, ground-item and player actions cannot select a worn or
			// inventory item for our score tooltip.
			default:
				return false;
		}
	}

	private static boolean isItemGroup(int group)
	{
		return group == InterfaceID.INVENTORY
			|| group == InterfaceID.WORNITEMS
			|| group == InterfaceID.EQUIPMENT_SIDE
			|| group == InterfaceID.BANKSIDE
			|| group == InterfaceID.SHARED_BANK_SIDE
			|| group == InterfaceID.BANKMAIN
			|| group == InterfaceID.SHARED_BANK
			|| group == InterfaceID.GE_OFFERS_SIDE
			|| group == InterfaceID.GE_OFFERS
			|| group == InterfaceID.EQUIPMENT;
	}
}

