package com.raccooncoefficient.score;

import java.math.BigDecimal;

/**
 * Item's own verified stat score, optional complete-total delta, and an
 * explicitly labeled base-only delta when effects/other inputs are unknown.
 */
public final class GearScoreComparison
{
	public enum Verdict
	{
		BETTER,
		WORSE,
		EQUAL,
		UNKNOWN
	}

	private final boolean itemKnown;
	private final BigDecimal itemScore;
	private final BigDecimal delta;
	private final BigDecimal baseDelta;
	private final Verdict verdict;
	private final String modelLabel;

	private GearScoreComparison(
		boolean itemKnown,
		BigDecimal itemScore,
		BigDecimal delta,
		BigDecimal baseDelta,
		Verdict verdict)
	{
		this(itemKnown, itemScore, delta, baseDelta, verdict, null);
	}

	private GearScoreComparison(
		boolean itemKnown,
		BigDecimal itemScore,
		BigDecimal delta,
		BigDecimal baseDelta,
		Verdict verdict,
		String modelLabel)
	{
		this.modelLabel = modelLabel;
		this.itemKnown = itemKnown;
		this.itemScore = itemScore;
		this.delta = delta;
		this.baseDelta = baseDelta;
		this.verdict = verdict;
	}

	public static GearScoreComparison unknownItem()
	{
		return new GearScoreComparison(false, null, null, null, Verdict.UNKNOWN);
	}

	public static GearScoreComparison knownItem(BigDecimal itemScore, BigDecimal delta)
	{
		return new GearScoreComparison(true, itemScore, delta, null, verdict(delta));
	}

	public static GearScoreComparison knownItemUnknownDelta(BigDecimal itemScore)
	{
		return new GearScoreComparison(true, itemScore, null, null, Verdict.UNKNOWN);
	}

	/**
	 * A verified change in the fixed Wave 1 item-stat portion only.
	 * Never masquerade as the overall score change when set/passive
	 * coefficients, the equipment state, or other components are unknown.
	 */
	public static GearScoreComparison knownItemBaseOnlyDelta(BigDecimal itemScore, BigDecimal baseDelta)
	{
		if (itemScore == null || baseDelta == null)
		{
			throw new IllegalArgumentException("Item score and base delta are required");
		}
		return new GearScoreComparison(true, itemScore, null, baseDelta, Verdict.UNKNOWN);
	}

	private static Verdict verdict(BigDecimal delta)
	{
		if (delta.signum() > 0)
		{
			return Verdict.BETTER;
		}
		if (delta.signum() < 0)
		{
			return Verdict.WORSE;
		}
		return Verdict.EQUAL;
	}

	public boolean isItemKnown()
	{
		return itemKnown;
	}

	public BigDecimal getItemScore()
	{
		return itemScore;
	}

	/** Verified change in the complete scoring model, or null if unknown. */
	public BigDecimal getDelta()
	{
		return delta;
	}

	/** Base-only delta (NOT complete), or null when unavailable/not needed. */
	public BigDecimal getBaseDelta()
	{
		return baseDelta;
	}

	public Verdict getVerdict()
	{
		return verdict;
	}

	/** Same comparison tagged with the model that produced it (null = locked v1). */
	public GearScoreComparison withModelLabel(String label)
	{
		if (label == null ? modelLabel == null : label.equals(modelLabel))
		{
			return this;
		}
		return new GearScoreComparison(itemKnown, itemScore, delta, baseDelta, verdict, label);
	}

	public String getModelLabel()
	{
		return modelLabel;
	}
}

package com.raccooncoefficient.score;

import java.awt.Color;
import java.math.BigDecimal;
import java.math.RoundingMode;

/** Player-facing score lines. The equipment screen draws the raccoon beside the equipment line. */
public final class GearScoreText
{
	public static final Color BETTER = new Color(0x00, 0xC8, 0x46);
	public static final Color WORSE = new Color(0xFF, 0x40, 0x40);
	public static final Color NEUTRAL = new Color(0xB4, 0xB4, 0xB4);
	public static final Color EQUIPMENT_ORANGE = new Color(0xFF, 0x98, 0x1F);

	private GearScoreText()
	{
	}

	public static String equipmentLine(GearScoreBreakdown score)
	{
		String number = score.displayedTotal().toPlainString();
		String prefix = score.getModelLabel() == null
			? "Gear Score: " : "Gear Score " + score.getModelLabel() + ": ";
		if (!score.isComplete())
		{
			return prefix + number + " ?";
		}
		return prefix + number;
	}

	/** Short fallback used only when the full Equipment Stats header cannot fit. */
	public static String compactEquipmentLine(String fullLine)
	{
		if (fullLine == null)
		{
			return "GS: ?";
		}
		if (fullLine.startsWith("Gear Score: "))
		{
			return "GS: " + fullLine.substring("Gear Score: ".length());
		}
		if (fullLine.startsWith("Gear Score "))
		{
			return "GS " + fullLine.substring("Gear Score ".length());
		}
		return fullLine;
	}

	/**
	 * Tooltip body, or null when the hovered id is not verified equipment and
	 * is not currently worn. The first line is left untagged so it stays white.
	 */
	public static String tooltip(GearScoreComparison comparison, boolean worn)
	{
		if (!comparison.isItemKnown())
		{
			if (!worn)
			{
				return null;
			}
			return "Gear Score: unknown";
		}

		StringBuilder text = new StringBuilder();
		text.append("Gear Score: ").append(comparison.getItemScore().toPlainString());
		text.append("</br>");
		if (comparison.getModelLabel() != null)
		{
			text.append(color(NEUTRAL, comparison.getModelLabel() + " "));
		}
		switch (comparison.getVerdict())
		{
			case BETTER:
				text.append(color(BETTER, "\u2191 " + formatDelta(comparison.getDelta())));
				break;
			case WORSE:
				text.append(color(WORSE, "\u2193 " + formatDelta(comparison.getDelta())));
				break;
			case EQUAL:
				text.append(color(NEUTRAL, "\u2192 " + formatDelta(comparison.getDelta())));
				break;
			case UNKNOWN:
			default:
				if (comparison.getBaseDelta() != null)
				{
					BigDecimal baseDelta = comparison.getBaseDelta();
					Color tint = baseDelta.signum() > 0 ? BETTER
						: baseDelta.signum() < 0 ? WORSE : NEUTRAL;
					String arrow = baseDelta.signum() > 0 ? "\u2191"
						: baseDelta.signum() < 0 ? "\u2193" : "\u2192";
					text.append("Base ");
					text.append(color(tint, arrow + " " + formatDelta(baseDelta)));
					text.append(color(NEUTRAL, " (total ?)"));
				}
				else
				{
					text.append(color(NEUTRAL, "\u2192 ?"));
				}
				break;
		}
		return text.toString();
	}

	public static String formatDelta(BigDecimal delta)
	{
		BigDecimal scaled = delta.setScale(1, RoundingMode.HALF_UP);
		int sign = scaled.signum();
		if (sign > 0)
		{
			return "+" + scaled.toPlainString();
		}
		if (sign < 0)
		{
			return "\u2212" + scaled.abs().toPlainString();
		}
		return "0.0";
	}

	private static String color(Color color, String text)
	{
		return String.format("<col=%02x%02x%02x>%s</col>", color.getRed(), color.getGreen(), color.getBlue(), text);
	}
}

package com.raccooncoefficient.score;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.List;

/**
 * EXPERIMENTAL, NOT WIRED INTO RUNE LITE UI.
 *
 * Gear Score v2 stat-distribution hypothesis based on owner-observed item
 * comparisons. These values are proposals, NOT claims about actual DPS.
 * Full set/weapon conditional effects remain separately unresolved.
 *
 * The production RaccoonCoefficientPlugin, hover display and equipped total
 * still call GearScoreCalculator.wave3(), using the locked Wave 1 formula.
 */
public final class GearScoreV2Preview
{
	private static final BigDecimal PHYSICAL_ATTACK = new BigDecimal("0.10");
	private static final BigDecimal RANGED_ATTACK = new BigDecimal("0.10");
	private static final BigDecimal MAGIC_ATTACK = new BigDecimal("0.40");
	private static final BigDecimal DEFENCE = new BigDecimal("0.08");
	private static final BigDecimal MELEE_STRENGTH = new BigDecimal("0.30");
	// Preserve the proven v1 Ranged Strength weight until a representative
	// ranged equipment and ammunition study justifies any reduction.
	private static final BigDecimal RANGED_STRENGTH = new BigDecimal("1.00");
	private static final BigDecimal MAGIC_DAMAGE_PERCENT = new BigDecimal("2.00");
	private static final BigDecimal PRAYER = new BigDecimal("0.50");

	private GearScoreV2Preview()
	{
	}

	public static BigDecimal itemRaw(EquipmentBonus bonus)
	{
		if (bonus == null)
		{
			throw new IllegalArgumentException("No score for unverified equipment stats");
		}

		// All signed bonuses are preserved, including negative attack/defence.
		int physicalAttack = bonus.getAttackStab()
			+ bonus.getAttackSlash()
			+ bonus.getAttackCrush();
		int defence = bonus.getDefenceStab()
			+ bonus.getDefenceSlash()
			+ bonus.getDefenceCrush()
			+ bonus.getDefenceMagic()
			+ bonus.getDefenceRanged();

		return BigDecimal.valueOf(physicalAttack).multiply(PHYSICAL_ATTACK)
			.add(BigDecimal.valueOf(bonus.getAttackRanged()).multiply(RANGED_ATTACK))
			.add(BigDecimal.valueOf(bonus.getAttackMagic()).multiply(MAGIC_ATTACK))
			.add(BigDecimal.valueOf(defence).multiply(DEFENCE))
			.add(BigDecimal.valueOf(bonus.getMeleeStrength()).multiply(MELEE_STRENGTH))
			.add(BigDecimal.valueOf(bonus.getRangedStrength()).multiply(RANGED_STRENGTH))
			.add(bonus.getMagicDamagePercent().multiply(MAGIC_DAMAGE_PERCENT))
			.add(BigDecimal.valueOf(bonus.getPrayer()).multiply(PRAYER));
	}

	public static BigDecimal itemDisplay(EquipmentBonus bonus)
	{
		return itemRaw(bonus).setScale(1, RoundingMode.HALF_UP);
	}

	/**
	 * Only report a total when all *item stats* are verified. This is strictly
	 * a BASE score, not a complete set/weapon passive effectiveness estimate.
	 * No unapproved set-effect numbers are ever added.
	 */
	public static BigDecimal verifiedBaseTotal(List<WornItem> worn, ItemStatSource stats)
	{
		if (worn == null || stats == null || WornLayout.hasDuplicateOccupiedSlot(worn))
		{
			return null;
		}
		BigDecimal total = BigDecimal.ZERO;
		for (WornItem item : worn)
		{
			if (item == null || item.getItemId() < 0)
			{
				continue;
			}
			EquipmentBonus bonus = stats.getVerifiedBonus(item.getItemId());
			if (bonus == null)
			{
				return null;
			}
			total = total.add(itemRaw(bonus));
		}
		return total.setScale(1, RoundingMode.HALF_UP);
	}

	public static String policy()
	{
		return "EXPERIMENTAL v2; no live scoring, no universal set/passive weights";
	}
}

